package com.example.nailsalon.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.stereotype.Service; import org.springframework.beans.factory.annotation.Value; import java.nio.charset.StandardCharsets; import java.security.Key; import java.util.Date;
@Service public class JwtService { private final Key key; public JwtService(@Value("${app.jwt.secret:NailSalonGrade5SecretKey-2026-LongEnough-For-HS256}") String secret){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String generate(String login,String role){return Jwts.builder().subject(login).claim("role",role).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+86400000)).signWith(key).compact();} public Claims parse(String token){return Jwts.parser().verifyWith((javax.crypto.SecretKey)key).build().parseSignedClaims(token).getPayload();} }
